    ll m1 = v;
    ll cnt = 0, p;

    if (m1 % 2 == 1) {
        p = 1;
    } else {
        p = 2;
    }

    while (m1 <= n) {
        if (m1 + p - 1 <= n) {
            cnt += p;
            p *= 2;
            m1 *= 2;
        } else {
            cnt += n - m1 + 1;
            break;
        }
    }

    return cnt;
}

