    data();
    scanf("%lld %lld", &n, &k);

    ll l = 1, r = n;

    while (l < r) {
        ll m = (l + r) / 2;
        ll cnt = rec(m + m % 2, n);

        if (cnt > k) {
            l = m + 1;
        } else {
            r = m;
        }
    }

    ll m = l;
    ll ans = -1;

    for (ll i = max(m - 1000LL, 1LL); i <= min(n, m + 1000LL); ++i) {
        ll cnt = rec(i, n);
        if (cnt >= k) {
            ans = max(i, ans);
        }
    }

    printf("%lld", ans);
    return 0;
}

